import "server-only";
import { db } from "@/lib/db";
import { deployHref } from "@/lib/deploy-intent";
import { hostingAppMenu } from "@/lib/hosting-app-menu";
import { esc, productLd, usd } from "./lib";
import { andList, hostingPromoActive } from "./products-common";

/**
 * The renewal chart's "typical intro-price host": $/mo in year 1, 2, 3, 4.
 * NOT Nxeon data — illustrative market figures (a low intro price that
 * renews higher), the same ones the live /web-hosting page shows and labels
 * "Illustrative comparison". The design states the assumption on the page
 * but cites no external source; kept pending the owner's decision.
 */
const TYPICAL_HOST = [2.99, 10.99, 14.99, 14.99];

/** The design's one-line "for" copy per plan when the plan has no tagline. */
const FOR_FALLBACK = "Shared hosting with free SSL, email and SFTP.";

/** /web-hosting — db.hostingPlan (what checkout sells), the real one-click app
 *  catalogue, and the first-month-free gate checkout applies. */
export async function load(_p: Record<string, string>) {
  const [plans, promo] = await Promise.all([
    db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    hostingPromoActive(),
  ]);
  if (!plans.length) throw new Error("nxm /web-hosting: no active hosting plans");

  const web = plans.map((p) => ({
    n: p.name, p: p.priceCents / 100, st: p.diskGB, sites: p.maxSites, db: p.maxDatabases, bw: p.bandwidthTB,
    f: p.tagline || FOR_FALLBACK,
    href: deployHref({ service: "hosting", hostingPlanId: p.id }),
  }));
  // "Best for you" starts on the admin's featured plan (the live page's
  // "Most popular"), else the middle one.
  const featured = plans.findIndex((p) => p.featured);
  const fit = featured >= 0 ? featured : Math.floor((plans.length - 1) / 2);

  // Renewal chart: Nxeon's flat line is that plan's real price; the slider
  // starts at 3 years, like the design.
  const rp = plans[fit];
  const years = 3;
  const a = rp.priceCents * 12 * years;
  const b = Math.round(TYPICAL_HOST.slice(0, years).reduce((s, v) => s + v * 100 * 12, 0));

  // One-click apps: the installer's own catalogue (WordPress + worker recipes).
  const apps = hostingAppMenu().map((x) => x.name);
  if (apps.length < 3) throw new Error("nxm /web-hosting: app catalogue unavailable");
  const span = (n: string) => `<span>${esc(n)}</span>`;
  const row = apps.map(span).join("");
  const rev = [...apps].reverse().map(span).join("");

  return {
    data: { web, fit, rn: rp.priceCents / 100, typ: TYPICAL_HOST, promo, cta: promo ? "Start free" : "Get started" },
    jsonLd: [productLd("Nxeon Web Hosting",
      "Fast shared web hosting with PHP, MySQL databases, free SSL, email and one-click WordPress — no server to manage.",
      "/web-hosting", plans.map((p) => ({ name: p.name, price: p.priceCents / 100 })))],
    slots: {
      "promo.pill": promo ? "First month free on every plan" : "Flat monthly pricing on every plan",
      "promo.cta": promo ? "Start free" : "Get started",
      "promo.plansLede": promo ? "Every plan starts with a free first month. " : "",
      "promo.final": promo
        ? "First month free, flat pricing after that, and free migration if you’re moving."
        : "Flat monthly pricing, and free migration if you’re moving.",
      "apps.count": String(apps.length),
      "apps.lead": `${andList(apps.slice(0, 3))} and ${apps.length - 3} more install themselves in one click.`,
      "apps.chips:html": apps.slice(0, 6).map((n, i) => `<span${i === 0 ? ' class="on"' : ""}>${esc(n)}</span>`).join(""),
      "apps.marquee:html": `<div>${row}${row}</div><div class="rev">${rev}${rev}</div>`,
      "rn.plan": rp.name,
      "rn.price": usd(rp.priceCents),
      "rn.a": usd(a), "rn.b": usd(b), "rn.s": usd(b - a),
      "rn.typ1": usd(TYPICAL_HOST[0] * 100), "rn.typ2": usd(TYPICAL_HOST[1] * 100), "rn.typ3": usd(TYPICAL_HOST[2] * 100),
    },
  };
}

