import "server-only";
import { db } from "@/lib/db";
import { deployHref } from "@/lib/deploy-intent";
import { productLd, usd } from "./lib";
import { supportLine } from "./products-common";

/**
 * Competitor data (NOT ours): Google Workspace Business Starter, $7 per user
 * per month on annual billing, $8.40 on the monthly (flexible) plan —
 * Google's public price list, https://workspace.google.com/pricing (after the
 * 2025 price change; the design states it "as of 2026"). Used for the note,
 * the per-seat bar and the savings maths.
 */
const GOOGLE_STARTER = { annual: 7, monthly: 8.4, asOf: "2026" };

/** The design's one-line "for" copy, keyed by plan name (the live page's
 *  TAGLINES). EmailPlan has no marketing copy of its own. */
const FOR: Record<string, string> = {
  Starter: "A professional inbox for you.",
  Business: "Email for a small team.",
  Pro: "Room for the whole company.",
};

const money = (d: number) => usd(Math.round(d * 100));

/** /business-email — db.emailPlan, exactly what checkout sells. */
export async function load(_p: Record<string, string>) {
  const plans = await db.emailPlan.findMany({
    where: { active: true },
    orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }],
  });
  const priced = plans.filter((p) => p.priceCents > 0 && p.mailboxes > 0);
  if (!priced.length) throw new Error("nxm /business-email: no active email plans");

  const mail = priced.map((p) => ({
    n: p.name,
    p: p.priceCents / (p.termMonths > 1 ? p.termMonths : 1) / 100,
    box: p.mailboxes, gb: p.storageGB,
    f: FOR[p.name] ?? "Professional email on your own domain.",
    href: deployHref({ service: "email", emailPlanId: p.id }),
  }));
  // "Most popular": the middle tier, as on the live page.
  const pop = mail.length > 1 ? Math.floor((mail.length - 1) / 2) : -1;

  // Seat calculator, initial state (the design starts at 5 people).
  const maxBox = Math.max(...mail.map((m) => m.box));
  const n = Math.min(5, maxBox);
  const fits = mail.filter((m) => m.box >= n);
  const pick = fits.length ? fits.reduce((x, y) => (x.p <= y.p ? x : y)) : mail[mail.length - 1];
  const them = n * GOOGLE_STARTER.annual;
  const save = (them - pick.p) * 12;

  return {
    data: { mail, pop, seat: GOOGLE_STARTER.annual },
    jsonLd: [productLd("Nxeon Business Email",
      "Professional email hosting on your own domain — SPF/DKIM/DMARC configured for you, webmail, IMAP/SMTP, spam and virus filtering, and free migration.",
      "/business-email", mail.map((m) => ({ name: m.n, price: m.p })))],
    slots: {
      "mail.from": money(Math.min(...mail.map((m) => m.p))),
      "se.max": String(maxBox), "se.n": String(n),
      "se.plan": pick.n, "se.av": `${money(pick.p)}/mo`, "se.bv": `${money(them)}/mo`,
      "se.s": save > 0 ? money(save) : "$0.00",
      "gw.annual": `$${GOOGLE_STARTER.annual}`, "gw.monthly": money(GOOGLE_STARTER.monthly), "gw.asOf": GOOGLE_STARTER.asOf,
      "support.line": supportLine(),
    },
  };
}
EOF
