import "server-only";
import { usd } from "./lib";
import { andList, annualMonthlyCents, hostingPromoActive, regionFacts, scriptJson, vpsPlanBySlug } from "./products-common";
import { REGION_COUNTRY } from "@/lib/node-regions";
import { BODY_HTML } from "../_pages/vps-vs-digitalocean/content";

/**
 * DigitalOcean's side — competitor data, NOT ours. Public prices from
 * https://www.digitalocean.com/pricing/droplets (Basic Droplets, Regular SSD,
 * monthly) and its backup rates (weekly 20% / daily 30% of the Droplet
 * price), checked September 2026 — the date the page's source line states.
 * Each is DigitalOcean's closest Droplet to the Nxeon plan named by slug.
 */
export const DIGITALOCEAN = {
  checked: "September 2026",
  dailyBackupRate: 0.3,
  match: [
    { slug: "starter", cpu: 1, ram: 2, disk: 50, bw: 2, price: 12 },
    { slug: "standard", cpu: 2, ram: 4, disk: 80, bw: 4, price: 24 },
    { slug: "pro", cpu: 4, ram: 8, disk: 160, bw: 5, price: 48 },
  ],
};

const gb = (mb: number) => Math.round((mb / 1024) * 10) / 10;
const d2 = (x: number) => usd(Math.round(x * 100));
const v = (x: number) => x.toFixed(3);

/** What DigitalOcean's closest plan has more of — the design's honest line,
 *  derived from both real spec sheets so it can never go stale. */
function honest(nx: { cpu: number; ram: number; disk: number; bw: number }, t: { cpu: number; ram: number; disk: number; bw: number }) {
  const more: string[] = [];
  if (t.cpu > nx.cpu) more.push(t.cpu - nx.cpu === 1 ? "one more vCPU" : `${t.cpu - nx.cpu} more vCPUs`);
  if (t.ram > nx.ram) more.push("more memory");
  if (t.disk > nx.disk) more.push("more disk");
  if (t.bw > nx.bw) more.push("more transfer");
  return more.length
    ? `DigitalOcean’s closest plan has ${andList(more)} at this size.`
    : "Nxeon matches or beats DigitalOcean’s specs at this size.";
}

/** Rows in the comparison table: the static ones + the promo row when shown. */
export function doVerdicts(promo: boolean) {
  const n = { w: 0, e: 0, l: 0 };
  for (const m of BODY_HTML.matchAll(/class="crow" data-v="([wel])"/g)) n[m[1] as "w" | "e" | "l"]++;
  if (promo) n.w++;
  return n;
}

/** /vps-vs-digitalocean — real Nxeon plans, annual rate, regions and promo. */
export async function load(_p: Record<string, string>) {
  const [promo, regions] = await Promise.all([hostingPromoActive(), regionFacts()]);
  const match = await Promise.all(DIGITALOCEAN.match.map(async (t) => {
    const p = await vpsPlanBySlug(t.slug);
    const nx = { cpu: p.cpuCores, ram: gb(p.ramMB), disk: p.diskGB, bw: p.bandwidthTB };
    const annual = (await annualMonthlyCents(p.priceCents)) / 100;
    return {
      name: p.name,
      spec: `${nx.cpu} vCPU, ${nx.ram} GB, ${nx.disk} GB NVMe, ${nx.bw} TB`,
      monthly: p.priceCents / 100, annual,
      tspec: `Basic ${t.cpu} vCPU, ${t.ram} GB, ${t.disk} GB SSD, ${t.bw} TB`,
      them: t.price,
      honest: honest(nx, t),
    };
  }));
  const bk = DIGITALOCEAN.dailyBackupRate;

  const cards = match.map((m) => {
    const them = m.them * (1 + bk), max = Math.max(m.monthly, them), save = them - m.monthly;
    return `<article class="au-glass muc"><h3>Nxeon ${m.name}</h3><p class="tier">vs the closest DigitalOcean Droplet</p><div class="mur">`
      + `<div class="n"><span><b>Nxeon ${m.name}</b><br>${m.spec}</span><em>${d2(m.monthly)}</em><i style="--v:${v(m.monthly / max)}"></i><small>Monthly, daily backups included. ${d2(m.annual)} on an annual term.</small></div>`
      + `<div class="t"><span><b>DigitalOcean</b><br>${m.tspec}</span><em>${d2(them)}</em><i style="--v:${v(them / max)}"></i><small>${d2(m.them)} Droplet + ${d2(m.them * bk)} for daily backups</small></div></div>`
      + `<div class="mu-save"><span>${save > 0 ? "You save every month" : "DigitalOcean costs less by"}</span><b>${d2(Math.abs(save))}</b></div>`
      + `<p class="mu-honest">${m.honest}</p></article>`;
  });

  // hero: the biggest real saving, per server per year, on the annual term
  const best = match.map((m) => ({ m, y: (m.them * (1 + bk) - m.annual) * 12 })).reduce((a, b) => (b.y > a.y ? b : a));
  const saveHtml = best.y > 0
    ? `<div class="au-glass vx-save"><small>Save up to</small><b class="big">$<span data-au-count="${Math.round(best.y)}">${Math.round(best.y)}</span></b><p>a year per server: Nxeon ${best.m.name} on an annual term against DigitalOcean’s closest Droplet with daily backups.</p>`
    : `<div class="au-glass vx-save"><small>Backups</small><b class="big">Included</b><p>on every Nxeon plan. DigitalOcean charges ${Math.round(bk * 100)}% of the Droplet price for daily backups.</p>`;
  const chips = [...(promo ? ["First month free on hosting"] : []), "Free migration", "Cancel anytime"];

  const rows = doVerdicts(promo);
  const sg = regions.regions.find((r) => REGION_COUNTRY[r.code] === "sg") ?? regions.regions[0];
  const plans = await Promise.all(["starter", "standard", "pro", "max"].map((s) => vpsPlanBySlug(s).catch(() => null)));
  const cheapest = Math.min(...plans.filter((p) => p).map((p) => p!.priceCents));

  return {
    jsonLd: [{
      "@context": "https://schema.org", "@type": "Product", name: "Nxeon Cloud VPS",
      description: "Managed NVMe cloud VPS with daily backups included, compared with DigitalOcean Droplets.",
      brand: { "@type": "Brand", name: "Nxeon" },
      offers: {
        "@type": "AggregateOffer", priceCurrency: "USD", lowPrice: (Math.min(...match.map((m) => m.monthly))).toFixed(2), offerCount: match.length,
        offers: match.map((m) => ({ "@type": "Offer", name: `${m.name} VPS`, price: m.monthly.toFixed(2), priceCurrency: "USD", availability: "https://schema.org/InStock" })),
      },
    }],
    slots: {
      "do.save:html": `${saveHtml}<div class="rv">${chips.map((c) => `<span>${c}</span>`).join("")}</div></div>`,
      "do.rows": String(rows.w + rows.e + rows.l),
      "do.mu:html": `<div class="mu">${cards.join("")}</div>`,
      "do.from": usd(cheapest),
      "do.fmfRow:html": promo
        ? '<div class="crow" data-v="w"><button type="button" aria-expanded="false"><b>First month free</b><span class="me">Included on hosting plans</span><span>Pay from day one</span><span class="cv-v w">Nxeon wins</span></button><div class="why"><p>New Nxeon hosting accounts get the first month on the house, so you can try the real thing first.</p></div></div>'
        : "",
      "regions.row": `${regions.count === 1 ? "One region" : `${regions.word.charAt(0).toUpperCase()}${regions.word.slice(1)} regions`}: ${regions.list}`,
      "regions.word": regions.word,
      "regions.list": regions.list,
      "promo.faq": promo ? ", plus the first month free on shared hosting" : "",
      "promo.final": promo ? "First month free on hosting plans, and a free migration off DigitalOcean." : "Daily backups included, and a free migration off DigitalOcean.",
      "do.n0": match[0].name, "do.n1": match[1].name, "do.n2": match[2].name,
      "do.match:html": scriptJson(match),
      "do.bk:html": scriptJson(bk),
      "demo.host": `nxeon-${REGION_COUNTRY[sg.code] ?? sg.code}-01`,
    },
  };
}
EOF
